const transfer = {
  cause: "For causation, separate underlying pressures from immediate triggers and choose the explanation that accounts for the most evidence.",
  comparison: "For comparison, use the same basis for both cases and preserve important similarities and differences.",
  context: "For context, identify the larger political, economic, social, or geographic process that made the event possible.",
  consequence: "For consequence, trace what changed and distinguish immediate effects from longer-term developments.",
  evidence: "For evidence, choose the information that most directly supports the claim rather than a detail that merely relates to the topic."
};

const categoryPrompts = {
  explain: ["Identify what the question asks you to explain or defend.", "Separate the strongest explanation from a trigger, consequence, or related detail."],
  use: ["Identify the historical model or pattern named in the question.", "Apply only the parts of that model supported by the bounded scenario."],
  connect: ["Identify the distinct lecture ideas the question asks you to connect.", "Look for a causal bridge, recurring pattern, or meaningful contrast between them."]
};

function I(category, move, lectures, stem, correct, wrong, claim, extra = {}) {
  return { category, move, lectures, stem, correct, wrong, claim, ...extra };
}

function makeQuestion(chapter, spec, number) {
  const base = [spec.correct, ...spec.wrong].map((pair, index) => ({ text: pair[0], feedback: pair[1], correct: index === 0 }));
  const longest = Math.max(...base.map(option => option.text.length));
  const neutralClauses = {
    explain: ["as an explanation of the broader historical pattern", "across the political and social setting examined here"],
    use: ["under the conditions and limits described in the scenario", "when the course model is applied to this case"],
    connect: ["when the lectures and their different evidence are considered together", "across the chapter's larger historical pattern"]
  }[spec.category];
  for (const option of base) {
    let clauseIndex = 0;
    while (option.text.length < longest * 0.72 && clauseIndex < neutralClauses.length) {
      option.text = `${option.text.replace(/[.]$/, "")}, ${neutralClauses[clauseIndex]}.`;
      clauseIndex += 1;
    }
  }
  const balancedLongest = Math.max(...base.map(option => option.text.length));
  for (const option of base) {
    if (option.text.length < balancedLongest / 1.6) {
      option.text = `${option.text.replace(/[.]$/, "")}, across the chapter's evidence.`;
    }
  }
  const shiftByPosition = { a: 0, b: 3, c: 2, d: 1 };
  const shift = spec.forcedPosition ? shiftByPosition[spec.forcedPosition] : number % 4;
  const arranged = base.slice(shift).concat(base.slice(0, shift));
  const letters = ["a", "b", "c", "d"];
  const choices = arranged.map((option, index) => ({ id: letters[index], text: option.text, feedback: option.feedback }));
  const correctChoiceId = choices[arranged.findIndex(option => option.correct)].id;
  const label = String(number).padStart(3, "0");
  return {
    id: `ch${String(chapter).padStart(2, "0")}-${spec.category}-${label}`,
    chapter,
    lectureIds: spec.lectures.map(n => `ch${String(chapter).padStart(2, "0")}-lec${String(n).padStart(2, "0")}`),
    category: spec.category,
    thinkingMove: spec.move,
    difficulty: spec.difficulty || "developing",
    status: "approved",
    practiceOnly: true,
    stem: spec.stem,
    choices,
    correctChoiceId,
    conciseCorrectFeedback: `Exactly. This is the strongest ${spec.move} answer.`,
    conciseIncorrectFeedback: spec.incorrect || `Not quite. Focus on the ${spec.move} relationship the question is testing.`,
    walkthrough: [
      ...categoryPrompts[spec.category],
      spec.step || `Compare each choice with the course evidence about ${spec.claim.toLowerCase()}.`,
      spec.correct[1]
    ],
    transferStrategy: transfer[spec.move],
    hint: spec.hint || `Ask which choice best fits this course claim: ${spec.claim}`,
    relatedQuestionFamily: spec.family || spec.claim,
    sourceAlignment: {
      primarySource: `Chapter ${chapter} approved background essay(s), Reveal lecture deck(s), and Historian's Notebook for lecture ${spec.lectures.join("/")}`,
      lectureClaim: spec.claim,
      notes: "Practice-only item written independently of secure exam materials."
    },
    accessibilityNotes: "Text-only item; no image or outside source is required."
  };
}

