function validateQuestions(chapter, questions) {
  const errors = [];
  const ids = new Set();
  for (const q of questions) {
    if (ids.has(q.id)) errors.push(`${chapter}: duplicate id ${q.id}`);
    ids.add(q.id);
    if (q.chapter !== chapter) errors.push(`${q.id}: wrong chapter`);
    if (!["explain", "use", "connect"].includes(q.category)) errors.push(`${q.id}: bad category`);
    if (!["cause", "comparison", "context", "consequence", "evidence"].includes(q.thinkingMove)) errors.push(`${q.id}: bad thinking move`);
    if (q.practiceOnly !== true || q.status !== "approved") errors.push(`${q.id}: practice boundary/status`);
    if (!Array.isArray(q.choices) || q.choices.length !== 4) errors.push(`${q.id}: choices`);
    if (!q.choices.some(c => c.id === q.correctChoiceId)) errors.push(`${q.id}: unresolved correct choice`);
    if (q.choices.some(c => !c.feedback || !c.text)) errors.push(`${q.id}: incomplete choice`);
    if (!Array.isArray(q.walkthrough) || q.walkthrough.length < 3 || q.walkthrough.length > 5) errors.push(`${q.id}: walkthrough`);
  }
  const counts = Object.fromEntries(["explain", "use", "connect"].map(cat => [cat, questions.filter(q => q.category === cat).length]));
  if (questions.length < 30 || questions.length > 45) errors.push(`${chapter}: total ${questions.length} outside 30–45`);
  if (counts.explain < 15 || counts.explain > 20) errors.push(`${chapter}: Explain ${counts.explain} outside 15–20`);
  if (counts.use < 8 || counts.use > 12) errors.push(`${chapter}: Use ${counts.use} outside 8–12`);
  if (counts.connect < 7 || counts.connect > 10) errors.push(`${chapter}: Connect ${counts.connect} outside 7–10`);
  return { errors, counts };
}

function buildReview(bank) {
  const lines = [
    `# Chapter ${bank.chapter} Question Review`, "",
    `**Chapter:** ${bank.chapterTitle}  `,
    `**Practice-only bank:** Yes  `,
    `**Default scaffolding:** ${bank.defaultScaffold}  `,
    `**Questions:** ${bank.questions.length}`, "",
    "## Source set", "",
    ...bank.sourceFiles.map(s => `- ${s}`), "",
    "## Questions", ""
  ];
  for (const q of bank.questions) {
    const correct = q.choices.find(c => c.id === q.correctChoiceId);
    lines.push(`### ${q.id} — ${q.category[0].toUpperCase() + q.category.slice(1)} / ${q.thinkingMove}`, "", q.stem, "");
    for (const c of q.choices) lines.push(`- ${c.id.toUpperCase()}. ${c.text}${c.id === q.correctChoiceId ? " **(best answer)**" : ""}`, `  - Feedback: ${c.feedback}`);
    lines.push("", `**Why this answer is strongest:** ${correct.feedback}`, "", "**Walk Me Through It**", "", ...q.walkthrough.map((s, i) => `${i + 1}. ${s}`), "", `**Transfer strategy:** ${q.transferStrategy}`, "", `**Source alignment:** ${q.sourceAlignment.lectureClaim}`, "", "---", "");
  }
  return lines.join("\n");
}

fs.mkdirSync(bankDir, { recursive: true });
fs.mkdirSync(reviewDir, { recursive: true });

const summary = [];
for (const chapter of Object.keys(chapters).map(Number)) {
  let existing = [];
  if (chapter === 2) {
    const pilot = JSON.parse(fs.readFileSync(path.join(root, ".backup-20260731-pilot", "banks", "chapter-02.json"), "utf8"));
    existing = pilot.questions;
  }
  const startByCategory = Object.fromEntries(["explain", "use", "connect"].map(cat => [cat, existing.filter(q => q.category === cat).length]));
  const generated = [];
  const ch2Positions = ["a", "b", "c", "d", "a", "b", "c", "d", "a", "b", "c", "d", "a", "b", "d"];
  for (const [additionIndex, spec] of additions[chapter].entries()) {
    startByCategory[spec.category] += 1;
    if (chapter === 2) spec.forcedPosition = ch2Positions[additionIndex];
    generated.push(makeQuestion(chapter, spec, startByCategory[spec.category]));
  }
  const questions = [...existing, ...generated];
  const result = validateQuestions(chapter, questions);
  if (result.errors.length) throw new Error(result.errors.join("\n"));
  const bank = {
    schemaVersion: "1.0",
    chapter,
    chapterTitle: chapters[chapter].title,
    studentTitle: `Think Like a Historian: Chapter ${chapter}`,
    defaultScaffold: chapters[chapter].scaffold,
    moduleReturnUrl: "",
    practiceOnly: true,
    sourceFiles: chapters[chapter].sources,
    lectureTitles: chapters[chapter].lectureTitles,
    questions
  };
  fs.writeFileSync(path.join(bankDir, `chapter-${String(chapter).padStart(2, "0")}.json`), `${JSON.stringify(bank, null, 2)}\n`);
  fs.writeFileSync(path.join(reviewDir, `chapter-${String(chapter).padStart(2, "0")}-question-review.md`), `${buildReview(bank)}\n`);
  summary.push({ chapter, total: questions.length, ...result.counts });
}

console.log(JSON.stringify(summary, null, 2));
